rv_series = chart_data['rolling_vol_sample']

# Annual data
annual_data = [
    (2000, 16.70, 9685308), (2001, 4.47, 11415045), (2002, -21.47, 13143867),
    (2003, 49.33, 11611470), (2004, 34.87, 9965114), (2005, -3.69, 13526498),
    (2006, 16.09, 14492086), (2007, 33.12, 14006711), (2008, -18.13, 17298704),
    (2009, 26.91, 14462778), (2010, 32.69, 11506208), (2011, 13.59, 12329367),
    (2012, 8.17, 10451951), (2013, 53.78, 7481007), (2014, 24.39, 7329387),
    (2015, 32.94, 7610103), (2016, -16.39, 9845206), (2017, 21.94, 9620935),
    (2018, 18.09, 7415417), (2019, 38.24, 6403171), (2020, 39.74, 7382078),
    (2021, 19.86, 6353806), (2022, -28.18, 7708901), (2023, -7.39, 7644710),
    (2024, -27.76, 11634710), (2025, -11.49, 16653856),
]

# Build JSON strings for charts
monthly_json = json.dumps(monthly)
dd_json = json.dumps(dd_series)
rv_json = json.dumps(rv_series)
