html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nike Inc. (NKE) Historical Stock Performance Analysis (2000–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {{
    --navy: #0a1628;
    --dark-blue: #122040;
    --mid-blue: #1a3a6e;
    --accent: #e87722;
    --accent2: #3a7bd5;
    --green: #2d9e6b;
    --red: #c0392b;
    --text: #e8eaf0;
    --text-muted: #8a9bb5;
    --border: #1e3254;
    --card-bg: #0f1e35;
    --card-bg2: #111f38;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    background: var(--navy);
    color: var(--text);
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
    font-size: 14px;
    line-height: 1.6;
  }}
  .header {{
    background: linear-gradient(135deg, #0a1628 0%, #122040 50%, #0e1a30 100%);
    border-bottom: 2px solid var(--accent);
    padding: 40px 60px 32px;
  }}
  .header-top {{
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 8px;
  }}
  .ticker-badge {{
    background: var(--accent);
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 1px;
    padding: 4px 14px;
    border-radius: 3px;
  }}
  .report-date {{
    color: var(--text-muted);
    font-size: 12px;
  }}
  h1 {{
    font-size: 28px;
    font-weight: 700;
    color: #fff;
    letter-spacing: -0.3px;
    margin-bottom: 6px;
  }}
  .subtitle {{
    color: var(--text-muted);
    font-size: 14px;
  }}
  .container {{
    max-width: 1200px;
    margin: 0 auto;
    padding: 40px 60px;
  }}
  /* KPI Cards */
  .kpi-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin: 32px 0;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px 18px;
    position: relative;
    overflow: hidden;
  }}
  .kpi-card::before {{
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--accent);
  }}
  .kpi-card.blue::before {{ background: var(--accent2); }}
  .kpi-card.green::before {{ background: var(--green); }}
  .kpi-card.red::before {{ background: var(--red); }}
  .kpi-card.purple::before {{ background: #7c5cbf; }}
  .kpi-label {{
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 8px;
  }}
  .kpi-value {{
    font-size: 28px;
    font-weight: 700;
    color: #fff;
    line-height: 1;
    margin-bottom: 4px;
  }}
  .kpi-sub {{
    font-size: 11px;
    color: var(--text-muted);
  }}
  /* Sections */
  .section {{
    margin-bottom: 48px;
  }}
  .section-header {{
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }}
  .section-num {{
    background: var(--accent);
    color: #fff;
    width: 26px; height: 26px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 700;
    flex-shrink: 0;
  }}
  h2 {{
    font-size: 18px;
    font-weight: 600;
    color: #fff;
  }}
  h3 {{
    font-size: 14px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 10px;
  }}
  p {{
    color: var(--text-muted);
    margin-bottom: 12px;
    line-height: 1.7;
  }}
  .chart-container {{
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 20px;
  }}
  .chart-title {{
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--text-muted);
    margin-bottom: 16px;
  }}
  canvas {{ max-height: 340px; }}
  /* Annotation boxes */
  .annotation-row {{
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
    margin-top: 16px;
  }}
  .annotation {{
    background: var(--card-bg2);
    border: 1px solid var(--border);
    border-left: 3px solid var(--accent);
    border-radius: 4px;
    padding: 12px 14px;
  }}
  .annotation.blue {{ border-left-color: var(--accent2); }}
  .annotation.green {{ border-left-color: var(--green); }}
  .annotation.red {{ border-left-color: var(--red); }}
  .annotation-label {{
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--text-muted);
    margin-bottom: 4px;
  }}
  .annotation-val {{
    font-size: 15px;
    font-weight: 700;
    color: #fff;
  }}
  .annotation-desc {{
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 2px;
  }}
  /* Table */
  .data-table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }}
  .data-table th {{
    background: var(--mid-blue);
    color: var(--text-muted);
    font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    padding: 10px 14px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }}
  .data-table td {{
    padding: 9px 14px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
  }}
  .data-table tr:last-child td {{ border-bottom: none; }}
  .data-table tr:hover td {{ background: rgba(255,255,255,0.02); }}
  .pos {{ color: #4caf82; font-weight: 600; }}
  .neg {{ color: #e05c5c; font-weight: 600; }}
  /* Phase boxes */
  .phase-grid {{
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-top: 16px;
  }}
  .phase-card {{
    background: var(--card-bg2);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 16px;
  }}
  .phase-card h4 {{
    font-size: 12px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--accent);
    margin-bottom: 6px;
  }}
  .phase-card h4.blue {{ color: var(--accent2); }}
  .phase-card h4.green {{ color: var(--green); }}
  .phase-card h4.red {{ color: var(--red); }}
  .phase-card p {{ font-size: 12px; margin-bottom: 0; }}
  /* Takeaways */
  .takeaway-list {{
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-top: 8px;
  }}
  .takeaway {{
